# 判断质数:只能被 1 和自己整除
n = int(input())
if n < 2:
    print(False)   # 0 和 1 不是质数
else:
    is_prime = True
    import math
    # 从 2 试到 sqrt(n) 即可(正因子成对出现)
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            is_prime = False
            break
    print(is_prime)

